import axios from 'axios';

const axiosInstance = axios.create({
    baseURL: 'http://localhost:5000/api',
});

axiosInstance.interceptors.request.use(
    async (config) => {
        // Добавляем токен из localStorage в заголовок Authorization
        const token = localStorage.getItem('token');
        console.log('Отправляемый токен:', token);
        if (token) {
            config.headers['Authorization'] = `Bearer ${token}`;
        }
        return config;
    },
    (error) => {
        
        console.error('Ошибка в запросе:', error);
        return Promise.reject(error);
    }
);

axiosInstance.interceptors.response.use(
    (response) => {
        
        return response;
    },
    async (error) => {
        const originalRequest = error.config;

        if (error.response?.status === 403 && !originalRequest._retry) {
            originalRequest._retry = true;

            try {
                console.log('Попытка обновления токена...');
                const { data } = await axios.post('http://localhost:5000/api/checker/refresh-token', null, {
                    withCredentials: true,
                });

                console.log('Новый accessToken получен:', data.accessToken);

                localStorage.setItem('token', data.accessToken);

                originalRequest.headers['Authorization'] = `Bearer ${data.accessToken}`;
                return axiosInstance(originalRequest);
            } catch (refreshError) {
                console.error('Ошибка при обновлении токена:', refreshError.message);

                localStorage.removeItem('token');
                window.location.href = '/';
                return Promise.reject(refreshError);
            }
        }

        return Promise.reject(error);
    }
);

export default axiosInstance;
